-- Authorized clean start for the eight-skill PPO combat model.
-- Production applies this transaction together with a new, untrained v10 row
-- generated by scripts/seed-robot-combat.mjs. No other application table changes.
begin;
alter table public.robot_shared_model drop constraint robot_shared_model_model_check;
delete from public.robot_shared_model where id='main';
alter table public.robot_shared_model add constraint robot_shared_model_model_check check (coalesce(jsonb_typeof(model)='object' and model->>'version'='10' and model->>'physicsVersion'='7' and model->>'policyKind'='joint-target-velocity-residual-pd-12joint-combat-v10' and not (model ? 'controllerArchive') and jsonb_typeof(model->'weights')='array' and jsonb_array_length(model->'weights')=4524 and octet_length(model::text)<=8388608,false));
commit;
notify pgrst,'reload schema';
